import { sdk as ImageKit } from '@wix/image-kit';

import type { UserDomainMediaConfig } from './../../ricos-types/index.js';
import { applyUserDomainMedia } from './../../_shared/media/apply-user-domain-media.js';

import type { GalleryMediaUrlRequest, GalleryMediaUrlResult } from './media-url-types.js';

/**
 * ImageKit options that keep gallery `src` / `srcSet` identical across SSR and
 * client hydration.
 *
 * `@wix/image-kit` otherwise reads `window.devicePixelRatio` (1 on the server,
 * often 2 on retina clients) and bakes it into CDN widths, which mismatches
 * React hydration. Density is already handled by the browser via `srcSet` +
 * `sizes`, so DPR must stay fixed at 1 here.
 */
const SSR_SAFE_IMAGE_KIT_OPTIONS = { devicePixelRatio: 1 } as const;

export const createGalleryMediaUrl = (
  { source, transformMode, targetWidths, targetRatio }: GalleryMediaUrlRequest,
  userDomainMedia?: UserDomainMediaConfig
): GalleryMediaUrlResult => {
  const { id, width: sourceWidth, height: sourceHeight } = source;
  if (!id || !isPositiveFinite(sourceWidth) || !isPositiveFinite(sourceHeight)) {
    return { src: applyUserDomainMedia(source.url, userDomainMedia) };
  }

  const widths = [...new Set(targetWidths.filter(isPositiveFinite).map(Math.round))]
    .filter(width => width > 0 && width <= sourceWidth)
    .sort((left, right) => left - right);

  if (widths.length === 0) {
    return { src: applyUserDomainMedia(source.url, userDomainMedia) };
  }

  try {
    const candidates = widths.map(width => {
      const height = Math.max(
        1,
        Math.round(
          isPositiveFinite(targetRatio) ? width / targetRatio : (width * sourceHeight) / sourceWidth
        )
      );
      const url =
        transformMode === 'fit'
          ? ImageKit.getScaleToFitImageURL(
              id,
              sourceWidth,
              sourceHeight,
              width,
              height,
              SSR_SAFE_IMAGE_KIT_OPTIONS
            )
          : ImageKit.getScaleToFillImageURL(
              id,
              sourceWidth,
              sourceHeight,
              width,
              height,
              SSR_SAFE_IMAGE_KIT_OPTIONS
            );
      return { url: applyUserDomainMedia(url, userDomainMedia), width };
    });

    return {
      src: candidates[candidates.length - 1].url,
      srcSet: candidates.map(({ url, width }) => `${url} ${width}w`).join(', '),
    };
  } catch {
    return { src: applyUserDomainMedia(source.url, userDomainMedia) };
  }
};

const isPositiveFinite = (value: number | undefined): value is number =>
  typeof value === 'number' && Number.isFinite(value) && value > 0;
