import React, { forwardRef, useCallback, useEffect, useImperativeHandle, useRef } from 'react';

import type { GalleryMediaRuntime } from './../../../plugin-gallery/media/gallery-media-types.js';
import { GalleryMedia } from './../../../plugin-gallery/media/gallery-media.js';
import { GalleryNavigationArrows } from './../../../plugin-gallery/media/gallery-navigation-arrows.js';
import type { NormalizedGalleryItem } from './../../../plugin-gallery/media/normalize-gallery-items.js';
import { useHorizontalNavigation } from './../../../plugin-gallery/media/use-horizontal-navigation.js';

import { FULLSCREEN_IMAGE_ITEM } from './data-hooks.js';
import styles from './fullscreen-scss.js';

const FULLSCREEN_TARGET_WIDTHS = [640, 960, 1280, 1920, 2560, 3840];

const pauseVideos = (element?: Element | null) => {
  Array.from(element?.getElementsByTagName('video') || []).forEach(video => video.pause());
};

export type FullscreenCarouselHandle = {
  activateItem: (index: number) => void;
};

type FullscreenCarouselProps = {
  items: NormalizedGalleryItem[];
  initialIndex: number;
  isMobile: boolean;
  runtime: GalleryMediaRuntime;
  galleryLabel: string;
  previousItemLabel: string;
  nextItemLabel: string;
  onActiveIndexChange: (index: number) => void;
};

export const FullscreenCarousel = forwardRef<FullscreenCarouselHandle, FullscreenCarouselProps>(
  function FullscreenCarousel(
    {
      items,
      initialIndex,
      isMobile,
      runtime,
      galleryLabel,
      previousItemLabel,
      nextItemLabel,
      onActiveIndexChange,
    },
    ref
  ) {
    const itemIds = items.map(item => item.id);
    const cellElements = useRef<(HTMLLIElement | null)[]>([]);
    const pauseLeavingItem = useCallback((fromIndex: number) => {
      pauseVideos(cellElements.current[fromIndex]);
    }, []);

    const {
      viewportRef,
      setCellRef,
      activeIndex,
      arrows,
      activateItem,
      clearPendingNavigation,
      getCellAccessibility,
    } = useHorizontalNavigation({
      itemIds,
      trackActiveItem: true,
      initialIndex,
      syncInitialScroll: true,
      scrollInline: 'start',
      deferInertWhileFocused: false,
      onActiveIndexChange,
      onBeforeActivate: pauseLeavingItem,
    });

    useEffect(
      () => () => {
        cellElements.current.forEach(pauseVideos);
      },
      []
    );

    useEffect(() => {
      cellElements.current.forEach((cell, index) => {
        if (index !== activeIndex) {
          pauseVideos(cell);
        }
      });
    }, [activeIndex]);

    useImperativeHandle(ref, () => ({ activateItem }), [activateItem]);

    return (
      <div className={styles.carousel}>
        {/*
          Fullscreen shares the navigation hook but not HorizontalTrack: it renders an
          ordered list of bare GalleryMedia rather than MediaCell, adds a mobile tabIndex
          for swipe focus, and pauses the video in the slide being left behind.
        */}
        <div
          ref={viewportRef}
          className={styles.viewport}
          aria-label={galleryLabel}
          data-hook="fullscreen-carousel"
          tabIndex={isMobile ? 0 : undefined}
          onPointerDown={clearPendingNavigation}
          onWheel={clearPendingNavigation}
        >
          <ol className={styles.track}>
            {items.map((item, index) => {
              const accessibility = getCellAccessibility(index);
              const inertAttributes = accessibility?.inert
                ? ({ inert: 'inert' } as React.HTMLAttributes<HTMLLIElement>)
                : {};
              return (
                <li
                  key={item.id}
                  ref={cell => {
                    cellElements.current[index] = cell;
                    setCellRef(index, cell);
                  }}
                  className={styles.slide}
                  aria-hidden={accessibility ? true : undefined}
                  data-hook={FULLSCREEN_IMAGE_ITEM}
                  data-id={item.id}
                  {...inertAttributes}
                >
                  <GalleryMedia
                    item={item}
                    presentation="fit"
                    sizes="100vw"
                    eager={index === activeIndex}
                    runtime={runtime}
                    targetWidths={FULLSCREEN_TARGET_WIDTHS}
                  />
                </li>
              );
            })}
          </ol>
          {!isMobile && arrows ? (
            <GalleryNavigationArrows
              previousLabel={previousItemLabel}
              nextLabel={nextItemLabel}
              previousClassName={styles.arrow}
              nextClassName={styles.arrow}
              {...arrows}
            />
          ) : null}
        </div>
      </div>
    );
  }
);
