import type { FocusEvent, FocusEventHandler } from 'react';
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';

import {
  getHorizontalGalleryScrollBehavior,
  getItemIdentity,
  scrollViewportByPage,
} from './horizontal-gallery-scroll.js';
import { useHorizontalScrollEdges } from './use-horizontal-scroll-edges.js';

type Direction = 'previous' | 'next';

/** Shrinks the observer root to a zero-width line down the middle of the viewport. */
const CENTER_LINE_ROOT_MARGIN = '0px -50% 0px -50%';

export type HorizontalArrows = {
  previousDisabled: boolean;
  nextDisabled: boolean;
  onPrevious: () => void;
  onNext: () => void;
  focusedArrow: Direction | undefined;
  onFocusedArrowChange: (direction: Direction | undefined) => void;
};

export type HorizontalCellAccessibility = {
  hidden: boolean;
  inert: boolean;
  onBlur: FocusEventHandler<HTMLLIElement>;
};

export type HorizontalNavigationOptions = {
  itemIds: readonly string[];
  /**
   * Opt in for layouts that show one item at a time (Fullsize, Fullscreen, FILL
   * Slider): the item under the viewport's centre becomes active and the rest
   * are hidden from assistive tech, and the arrows step item by item. Layouts
   * that show several items at once leave this off and only page the scroller.
   */
  trackActiveItem?: boolean;
  scrollInline?: ScrollLogicalPosition;
  initialIndex?: number;
  /**
   * When true, jump the viewport to `initialIndex` on mount / identity change
   * (fullscreen). When false, reset to `initialIndex` without forcing scrollLeft.
   */
  syncInitialScroll?: boolean;
  /** Delay inert until the previously active cell blurs. Default true. */
  deferInertWhileFocused?: boolean;
  onActiveIndexChange?: (index: number) => void;
  onBeforeActivate?: (fromIndex: number, toIndex: number) => void;
};

export type HorizontalNavigation = {
  viewportRef: React.RefObject<HTMLDivElement>;
  setCellRef: (index: number, element: HTMLLIElement | null) => void;
  activeIndex: number;
  /** `undefined` when there is nothing to page through, so no arrows render. */
  arrows: HorizontalArrows | undefined;
  activateItem: (index: number) => void;
  clearPendingNavigation: () => void;
  getCellAccessibility: (index: number) => HorizontalCellAccessibility | undefined;
};

const clampIndex = (index: number, itemCount: number) =>
  Math.min(Math.max(index, 0), Math.max(itemCount - 1, 0));

/**
 * Drives a horizontal gallery scroller: which item is active (when the layout
 * has one), and the state the navigation arrows render from.
 */
export const useHorizontalNavigation = ({
  itemIds,
  trackActiveItem = false,
  scrollInline = 'start',
  initialIndex = 0,
  syncInitialScroll = false,
  deferInertWhileFocused = true,
  onActiveIndexChange,
  onBeforeActivate,
}: HorizontalNavigationOptions): HorizontalNavigation => {
  const itemCount = itemIds.length;
  const itemIdentity = getItemIdentity(itemIds);
  const viewportRef = useRef<HTMLDivElement>(null);
  const cellRefs = useRef<(HTMLLIElement | null)[]>([]);
  const pendingNavigationIndex = useRef<number>();
  const [activeIndex, setActiveIndex] = useState(() => clampIndex(initialIndex, itemCount));
  const [deferredInertIndex, setDeferredInertIndex] = useState<number>();
  const [focusedArrow, setFocusedArrow] = useState<Direction>();
  const { allItemsFit, firstEdgeVisible, lastEdgeVisible } = useHorizontalScrollEdges({
    viewportRef,
    itemCount,
    itemIdentity,
  });

  const resetNavigationState = useCallback((nextIndex: number) => {
    setActiveIndex(nextIndex);
    setDeferredInertIndex(undefined);
    setFocusedArrow(undefined);
  }, []);

  useEffect(() => {
    if (syncInitialScroll) {
      return;
    }
    resetNavigationState(clampIndex(initialIndex, itemCount));
    pendingNavigationIndex.current = undefined;
  }, [initialIndex, itemCount, itemIdentity, resetNavigationState, syncInitialScroll]);

  useLayoutEffect(() => {
    if (!syncInitialScroll) {
      return;
    }
    const nextIndex = clampIndex(initialIndex, itemCount);
    const target = cellRefs.current[nextIndex];
    const viewport = viewportRef.current;

    resetNavigationState(nextIndex);
    pendingNavigationIndex.current = target ? nextIndex : undefined;
    if (viewport && target) {
      viewport.scrollLeft = target.offsetLeft;
    }
  }, [initialIndex, itemCount, itemIdentity, resetNavigationState, syncInitialScroll]);

  useEffect(() => {
    if (trackActiveItem) {
      onActiveIndexChange?.(activeIndex);
    }
  }, [activeIndex, onActiveIndexChange, trackActiveItem]);

  useEffect(() => {
    const viewport = viewportRef.current;
    const cells = cellRefs.current.slice(0, itemCount);
    if (
      !trackActiveItem ||
      !viewport ||
      cells.some(cell => !cell) ||
      typeof IntersectionObserver === 'undefined'
    ) {
      return;
    }

    const observer = new IntersectionObserver(
      entries => {
        // Only the cell straddling the centre line intersects, so any reported
        // intersection is the new active item. A cell boundary sitting exactly
        // on the line can report two, in which case the later one wins.
        const centered = entries.filter(entry => entry.isIntersecting).pop();
        const nextIndex = centered ? cells.indexOf(centered.target as HTMLLIElement) : -1;
        // The line can also fall into the gap between two cells, which reports
        // no intersection at all. Keep the last known item rather than clearing.
        if (nextIndex === -1) {
          return;
        }

        setActiveIndex(currentIndex => {
          const pendingIndex = pendingNavigationIndex.current;
          if (pendingIndex !== undefined) {
            if (nextIndex !== pendingIndex) {
              return currentIndex;
            }
            pendingNavigationIndex.current = undefined;
          }

          if (
            deferInertWhileFocused &&
            nextIndex !== currentIndex &&
            cells[currentIndex]?.contains(document.activeElement)
          ) {
            setDeferredInertIndex(currentIndex);
          }
          return nextIndex;
        });
      },
      { root: viewport, rootMargin: CENTER_LINE_ROOT_MARGIN, threshold: 0 }
    );

    cells.forEach(cell => observer.observe(cell as HTMLLIElement));
    return () => observer.disconnect();
  }, [deferInertWhileFocused, itemCount, itemIdentity, trackActiveItem]);

  const activateItem = useCallback(
    (index: number) => {
      const clampedIndex = clampIndex(index, itemCount);
      const target = cellRefs.current[clampedIndex];
      if (!target || clampedIndex === activeIndex) {
        return;
      }
      onBeforeActivate?.(activeIndex, clampedIndex);
      pendingNavigationIndex.current = clampedIndex;
      setActiveIndex(clampedIndex);
      target.scrollIntoView?.({
        behavior: getHorizontalGalleryScrollBehavior(),
        block: 'nearest',
        inline: scrollInline,
      });
    },
    [activeIndex, itemCount, onBeforeActivate, scrollInline]
  );

  const activatePage = (direction: Direction) => {
    const viewport = viewportRef.current;
    if (viewport) {
      scrollViewportByPage(viewport, direction);
    }
  };

  const clearPendingNavigation = () => {
    pendingNavigationIndex.current = undefined;
  };

  const setCellRef = (index: number, element: HTMLLIElement | null) => {
    cellRefs.current[index] = element;
  };

  const getCellAccessibility = (index: number): HorizontalCellAccessibility | undefined => {
    if (!trackActiveItem || index === activeIndex) {
      return undefined;
    }
    // Keep the outgoing cell reachable until focus leaves it, so a keyboard user
    // is never trapped inside a subtree that just became inert.
    const inert = !deferInertWhileFocused || index !== deferredInertIndex;
    return {
      hidden: inert,
      inert,
      onBlur: (event: FocusEvent<HTMLLIElement>) => {
        if (
          index === deferredInertIndex &&
          !event.currentTarget.contains(event.relatedTarget as Node | null)
        ) {
          setDeferredInertIndex(undefined);
        }
      },
    };
  };

  const arrows: HorizontalArrows | undefined =
    itemCount > 1 && !allItemsFit
      ? {
          previousDisabled: firstEdgeVisible,
          nextDisabled: lastEdgeVisible,
          onPrevious: trackActiveItem
            ? () => activateItem(activeIndex - 1)
            : () => activatePage('previous'),
          onNext: trackActiveItem
            ? () => activateItem(activeIndex + 1)
            : () => activatePage('next'),
          focusedArrow,
          onFocusedArrowChange: setFocusedArrow,
        }
      : undefined;

  return {
    viewportRef,
    setCellRef,
    activeIndex,
    arrows,
    activateItem,
    clearPendingNavigation,
    getCellAccessibility,
  };
};
