import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import ReactDOM from 'react-dom';

import type { TFunction, UserDomainMediaConfig } from './../../../ricos-types/index.js';
import { FocusManager } from './../../../_shared/focus-manager/focus-manager.js';
import { createGalleryMediaUrl } from './../../../plugin-gallery/media/create-gallery-media-url.js';
import type { GalleryMediaRuntime } from './../../../plugin-gallery/media/gallery-media-types.js';
import type { NormalizedGalleryItem } from './../../../plugin-gallery/media/normalize-gallery-items.js';

import {
  FULLSCREEN_CLOSE_BUTTON,
  FULLSCREEN_ROOT,
  FULLSCREEN_TOGGLE_BUTTON,
} from './data-hooks.js';
import type { FullscreenCarouselHandle } from './fullscreen-carousel.js';
import { FullscreenCarousel } from './fullscreen-carousel.js';
import styles from './fullscreen-scss.js';

export type FullscreenModalProps = {
  container?: HTMLElement | (() => HTMLElement | null);
} & InnerFullscreenProps;

const resolveFullscreenContainer = (
  container: HTMLElement | (() => HTMLElement | null) | undefined
): HTMLElement | null => {
  if (typeof container === 'function') {
    return container();
  }
  if (container) {
    return container;
  }
  if (typeof document === 'undefined') {
    return null;
  }
  return document.body;
};

export const FullscreenModal: React.FC<FullscreenModalProps> = ({ container, ...props }) => {
  const target = resolveFullscreenContainer(container);
  const fullscreen = <InnerFullscreen {...props} />;

  return target ? ReactDOM.createPortal(fullscreen, target) : fullscreen;
};

type InnerFullscreenProps = {
  items: NormalizedGalleryItem[];
  isMobile: boolean;
  index: number;
  backgroundColor?: string;
  foregroundColor?: string;
  onClose: () => void;
  restoreFocusTo?: HTMLElement;
  jsdomMode?: boolean;
  t: TFunction;
  userDomainMedia?: UserDomainMediaConfig;
};

const InnerFullscreen: React.FC<InnerFullscreenProps> = props => {
  const {
    backgroundColor = 'white',
    foregroundColor = '#2F2E2E',
    isMobile,
    items,
    restoreFocusTo,
    t,
  } = props;
  const initialIndex = Math.min(Math.max(props.index, 0), Math.max(items.length - 1, 0));
  const [activeIndex, setActiveIndex] = useState(initialIndex);
  const [isInFullscreen, setIsInFullscreen] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const closeButtonRef = useRef<HTMLButtonElement>(null);
  const carouselRef = useRef<FullscreenCarouselHandle>(null);
  const activeItem = items[activeIndex];
  const canUseBrowserFullscreen = !isMobile && Boolean(document.fullscreenEnabled);
  const mediaRuntime = useMemo<GalleryMediaRuntime>(
    () => ({
      createMediaUrl: request => createGalleryMediaUrl(request, props.userDomainMedia),
      playVideoLabel: t('Gallery_Play_Video_AriaLabel'),
    }),
    [props.userDomainMedia, t]
  );

  const restoreOpenerFocus = useCallback(() => {
    if (restoreFocusTo?.isConnected) {
      const previousTabIndex = restoreFocusTo.getAttribute('tabindex');
      if (restoreFocusTo.tabIndex < 0) {
        restoreFocusTo.setAttribute('tabindex', '-1');
      }
      restoreFocusTo.focus();
      restoreAttribute(restoreFocusTo, 'tabindex', previousTabIndex);
    }
  }, [restoreFocusTo]);

  const close = useCallback(async () => {
    pauseChildNodesVideos(containerRef.current);
    if (document.fullscreenElement === containerRef.current && document.exitFullscreen) {
      try {
        await document.exitFullscreen();
      } catch {
        // The modal must still close if the browser rejects exiting fullscreen.
      }
    }
    props.onClose();
    setTimeout(restoreOpenerFocus, 0);
  }, [props.onClose, restoreOpenerFocus]);

  const toggleFullscreenMode = useCallback(async () => {
    const element = containerRef.current;
    if (!element || !document.fullscreenEnabled) {
      return;
    }
    try {
      if (document.fullscreenElement === element) {
        await document.exitFullscreen?.();
      } else {
        await element.requestFullscreen?.();
      }
    } catch {
      // Fullscreen availability can change between rendering and activation.
    }
  }, []);

  useEffect(() => {
    if (items.length === 0) {
      props.onClose();
      return;
    }

    pauseChildNodesVideos(document);
    const focusCloseButton = setTimeout(() => closeButtonRef.current?.focus(), 0);
    const onEsc = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        void close();
      }
    };
    const onFullscreenChange = () =>
      setIsInFullscreen(document.fullscreenElement === containerRef.current);

    document.addEventListener('keydown', onEsc);
    document.addEventListener('fullscreenchange', onFullscreenChange);
    const releaseModalEnvironment = applyModalEnvironment(containerRef.current);

    return () => {
      clearTimeout(focusCloseButton);
      document.removeEventListener('keydown', onEsc);
      document.removeEventListener('fullscreenchange', onFullscreenChange);
      pauseChildNodesVideos(containerRef.current);
      releaseModalEnvironment();
    };
  }, [close, items.length, props.onClose]);

  if (!activeItem) {
    return null;
  }

  const onDialogKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.target instanceof HTMLVideoElement) {
      return;
    }
    if (event.key === 'ArrowLeft') {
      event.preventDefault();
      carouselRef.current?.activateItem(activeIndex - 1);
    } else if (event.key === 'ArrowRight') {
      event.preventDefault();
      carouselRef.current?.activateItem(activeIndex + 1);
    }
  };

  return (
    <FocusManager
      jsdomMode={props.jsdomMode}
      preventScroll
      focusTrapOptions={{
        initialFocus: () => closeButtonRef.current || false,
        returnFocusOnDeactivate: false,
        escapeDeactivates: false,
      }}
    >
      <div
        ref={containerRef}
        style={{ background: backgroundColor }}
        dir="ltr"
        data-hook={FULLSCREEN_ROOT}
        className={isInFullscreen ? styles.fullscreen_mode : styles.expand_mode}
        onContextMenu={event => activeItem.disableDownload && event.preventDefault()}
        onKeyDown={onDialogKeyDown}
        role="dialog"
        aria-modal="true"
        aria-label={t('Fullscreen_Gallery_AriaLabel', { count: items.length })}
      >
        {canUseBrowserFullscreen ? (
          <FullscreenToggleButton
            isInFullscreen={isInFullscreen}
            backgroundColor={backgroundColor}
            foregroundColor={foregroundColor}
            onToggleFullscreen={toggleFullscreenMode}
            t={t}
          />
        ) : null}
        <button
          ref={closeButtonRef}
          type="button"
          className={styles.close}
          onClick={() => void close()}
          aria-label={t('Fullscreen_Close_Button_AriaLabel')}
          data-hook={FULLSCREEN_CLOSE_BUTTON}
        >
          <CloseIcon backgroundColor={backgroundColor} foregroundColor={foregroundColor} />
        </button>
        <FullscreenCarousel
          ref={carouselRef}
          items={items}
          initialIndex={initialIndex}
          isMobile={isMobile}
          runtime={mediaRuntime}
          galleryLabel={t('Fullscreen_Gallery_AriaLabel', { count: items.length })}
          previousItemLabel={t('Gallery_Previous_Item_AriaLabel')}
          nextItemLabel={t('Gallery_Next_Item_AriaLabel')}
          onActiveIndexChange={setActiveIndex}
        />
        <span className={styles.visuallyHidden} role="status" aria-live="polite" aria-atomic="true">
          {activeItem.title
            ? t('Gallery_Show_Titled_Item_AriaLabel', {
                position: activeIndex + 1,
                title: activeItem.title,
              })
            : t('Gallery_Show_Item_AriaLabel', { position: activeIndex + 1 })}
        </span>
        {!isInFullscreen && activeItem.title ? (
          <div className={styles.info_container}>
            <div
              title={activeItem.title}
              style={{ color: foregroundColor }}
              className={styles.title}
            >
              {activeItem.title}
            </div>
          </div>
        ) : null}
      </div>
    </FocusManager>
  );
};

const applyModalEnvironment = (dialog: HTMLElement | null) => {
  if (!dialog) {
    return () => {};
  }

  const previousOverflow = document.body.style.overflow;
  const changedElements: {
    element: HTMLElement;
    inert: string | null;
    ariaHidden: string | null;
  }[] = [];
  let current: HTMLElement = dialog;

  document.body.style.overflow = 'hidden';
  while (current.parentElement) {
    const parent = current.parentElement;
    Array.from(parent.children).forEach(sibling => {
      if (sibling !== current && sibling instanceof HTMLElement) {
        changedElements.push({
          element: sibling,
          inert: sibling.getAttribute('inert'),
          ariaHidden: sibling.getAttribute('aria-hidden'),
        });
        sibling.setAttribute('inert', 'inert');
        sibling.setAttribute('aria-hidden', 'true');
      }
    });
    if (parent === document.body) {
      break;
    }
    current = parent;
  }

  return () => {
    document.body.style.overflow = previousOverflow;
    changedElements.forEach(({ element, inert, ariaHidden }) => {
      restoreAttribute(element, 'inert', inert);
      restoreAttribute(element, 'aria-hidden', ariaHidden);
    });
  };
};

const restoreAttribute = (element: HTMLElement, name: string, value: string | null) => {
  if (value === null) {
    element.removeAttribute(name);
  } else {
    element.setAttribute(name, value);
  }
};

const FullscreenToggleButton = ({
  isInFullscreen,
  backgroundColor,
  foregroundColor,
  onToggleFullscreen,
  t,
}: {
  isInFullscreen: boolean;
  backgroundColor?: string;
  foregroundColor?: string;
  onToggleFullscreen: () => void;
  t: TFunction;
}) => {
  const Icon = isInFullscreen ? ShrinkIcon : ExpandIcon;
  return (
    <button
      type="button"
      className={styles.expand_button}
      onClick={onToggleFullscreen}
      aria-label={
        isInFullscreen
          ? t('Fullscreen_Shrink_Button_AriaLabel')
          : t('Fullscreen_Expand_Button_AriaLabel')
      }
      data-hook={FULLSCREEN_TOGGLE_BUTTON}
    >
      <Icon backgroundColor={backgroundColor} foregroundColor={foregroundColor} />
    </button>
  );
};

const pauseChildNodesVideos = (element: Document | Element | null) =>
  Array.from(element?.getElementsByTagName('video') || []).forEach(video => video.pause());

